-- DataMigration : peuple "Plan de l'hôtel" (image schématique) et les photos
-- de chambres pour Hôtel Churchill (images générées en SVG, faute de plan
-- architectural réel/shooting photo) — cf. prisma/roomMedia.ts, seule
-- source de vérité pour ces images (seed.ts et cette migration l'importent
-- toutes les deux). Chaque valeur n'est posée QUE si elle est encore vide
-- (IS NULL / tableau vide), pour ne jamais écraser un plan ou des photos
-- déjà mis en ligne manuellement depuis l'admin.

UPDATE "EntityModuleConfig" SET "hotelPlan"='data:image/svg+xml;base64,' WHERE "hotelPlan" IS NULL AND "entityId" IN (SELECT "id" FROM "Entity" WHERE "code"='E00000001');

UPDATE "Room" SET "photos"='["data:image/svg+xml;base64,","data:image/svg+xml;base64,"]'::jsonb WHERE "code"='A11' AND "entityId" IN (SELECT "id" FROM "Entity" WHERE "code"='E00000001') AND ("photos"='[]'::jsonb OR "photos" IS NULL);
UPDATE "Room" SET "x"=70, "y"=110 WHERE "code"='A11' AND "entityId" IN (SELECT "id" FROM "Entity" WHERE "code"='E00000001') AND "x" IS NULL AND "y" IS NULL;

